create table public.together_consents(user_id uuid primary key references auth.users(id) on delete cascade,adult_confirmed_at timestamptz not null,terms_version text not null,privacy_version text not null,accepted_at timestamptz not null default now());
alter table public.together_consents enable row level security;revoke all on public.together_consents from public,anon,authenticated;
create function public.together_my_consent() returns table(adult_confirmed_at timestamptz,terms_version text,privacy_version text,accepted_at timestamptz) language sql security definer set search_path='' stable as $$select c.adult_confirmed_at,c.terms_version,c.privacy_version,c.accepted_at from public.together_consents c where c.user_id=auth.uid()$$;
create function public.together_accept_rules(p_adult boolean,p_terms_version text,p_privacy_version text) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or p_adult is not true then raise exception 'adult confirmation required' using errcode='42501';end if;if p_terms_version<>'2026-11-18' or p_privacy_version<>'2026-11-18' then raise exception 'invalid document version' using errcode='22023';end if;insert into public.together_consents(user_id,adult_confirmed_at,terms_version,privacy_version) values(auth.uid(),now(),p_terms_version,p_privacy_version) on conflict(user_id) do update set adult_confirmed_at=excluded.adult_confirmed_at,terms_version=excluded.terms_version,privacy_version=excluded.privacy_version,accepted_at=now();end$$;
revoke all on function public.together_my_consent(),public.together_accept_rules(boolean,text,text) from public,anon;grant execute on function public.together_my_consent(),public.together_accept_rules(boolean,text,text) to authenticated;

alter table public.together_messages add column recipient_id uuid references auth.users(id) on delete cascade;
update public.together_messages x set recipient_id=case when m.user_a=x.sender_id then m.user_b else m.user_a end from public.together_matches m where m.id=x.match_id;
alter table public.together_messages alter column recipient_id set not null;
alter table public.together_messages add column read_at timestamptz;
create index together_messages_unread on public.together_messages(recipient_id,read_at) where read_at is null;
drop function public.together_send_message(uuid,text);
create function public.together_send_message(p_match_id uuid,p_body text) returns void language plpgsql security definer set search_path='' as $$declare m public.together_matches;r uuid;begin if auth.uid() is null then raise exception 'authentication required' using errcode='42501';end if;select * into m from public.together_matches where id=p_match_id;if m.id is null or auth.uid() not in(m.user_a,m.user_b) then raise exception 'match unavailable' using errcode='42501';end if;if exists(select 1 from public.together_blocks b where (b.blocker_id=m.user_a and b.blocked_id=m.user_b) or (b.blocker_id=m.user_b and b.blocked_id=m.user_a)) then raise exception 'contact blocked' using errcode='42501';end if;r:=case when m.user_a=auth.uid() then m.user_b else m.user_a end;insert into public.together_messages(match_id,sender_id,recipient_id,body) values(p_match_id,auth.uid(),r,btrim(p_body));end$$;
drop function public.together_match_messages(uuid);
create function public.together_match_messages(p_match_id uuid) returns table(id bigint,mine boolean,body text,created_at timestamptz) language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.together_matches m where m.id=p_match_id and auth.uid() in(m.user_a,m.user_b)) then raise exception 'match unavailable' using errcode='42501';end if;update public.together_messages set read_at=coalesce(read_at,now()) where match_id=p_match_id and recipient_id=auth.uid();return query select x.id,x.sender_id=auth.uid(),x.body,x.created_at from public.together_messages x where x.match_id=p_match_id order by x.created_at asc limit 200;end$$;
drop function public.together_my_matches();
create function public.together_my_matches() returns table(match_id uuid,display_name text,city text,bio text,interests text[],photo_path text,matched_at timestamptz,unread_count bigint) language sql security definer set search_path='' stable as $$select m.id,p.display_name,p.city,p.bio,p.interests,p.photo_path,m.created_at,(select count(*) from public.together_messages x where x.match_id=m.id and x.recipient_id=auth.uid() and x.read_at is null) from public.together_matches m join public.together_discovery_profiles p on p.user_id=case when m.user_a=auth.uid() then m.user_b else m.user_a end where auth.uid() is not null and (m.user_a=auth.uid() or m.user_b=auth.uid()) and not exists(select 1 from public.together_blocks b where (b.blocker_id=m.user_a and b.blocked_id=m.user_b) or (b.blocker_id=m.user_b and b.blocked_id=m.user_a)) order by m.created_at desc$$;
revoke all on function public.together_send_message(uuid,text),public.together_match_messages(uuid),public.together_my_matches() from public,anon;grant execute on function public.together_send_message(uuid,text),public.together_match_messages(uuid),public.together_my_matches() to authenticated;
